17	package org.springframework.samples.petclinic.util;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.Locale;
23	
24	/**
25	 * Helpers backing the owner duplicate-detection identity key. The identity key is the lower-case
26	 * SHA-256 hex of the owner's normalized telephone, lower-cased email and the American Soundex code of
27	 * the last name, joined with {@code '|'} (see {@code OwnerMapper.toIdentityKey}). Both the key itself
28	 * and the soft-match (which compares the Soundex code and postcode) route through this single source of
29	 * truth, so the two cannot diverge.
30	 *
31	 * <p>These are deliberately plain {@code static} utilities in their own class rather than default
32	 * methods on the MapStruct owner mapper: a {@code String -> String} mapper method would be picked up by
33	 * MapStruct as an implicit type conversion and wrongly applied to unrelated String properties.
34	 */
35	public final class IdentityKeyUtils {
36	
37	    private IdentityKeyUtils() {
38	    }
39	
40	    /**
41	     * Computes the American Soundex code of a name: the (upper-cased) first letter followed by three
42	     * digits, zero-padded or truncated to exactly four characters. Consonants are coded 1-6 by group;
43	     * vowels and {@code H}/{@code W} are not coded. Adjacent letters with the same code, and same-code
44	     * letters separated only by {@code H} or {@code W}, collapse to a single digit, while same-code
45	     * letters separated by a vowel are coded separately. Non-letters are ignored.
46	     *
47	     * @param name the name to encode, possibly {@code null}
48	     * @return the four-character Soundex code, or {@code ""} when the name has no letters
49	     */
50	    public static String soundex(String name) {
51	        if (name == null) {
52	            return "";
53	        }
54	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
55	        if (letters.isEmpty()) {
56	            return "";
57	        }
58	        StringBuilder code = new StringBuilder();
59	        code.append(letters.charAt(0));
60	        char previousDigit = digit(letters.charAt(0));
61	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
62	            char c = letters.charAt(i);
63	            char d = digit(c);
64	            if (d != '0' && d != previousDigit) {
65	                code.append(d);
66	            }
67	            // A vowel resets the "previous digit" so a following same-code consonant is coded again;
68	            // H and W are transparent, keeping the previous digit so they cannot separate a repeat.
69	            if (c != 'H' && c != 'W') {
70	                previousDigit = d;
71	            }
72	        }
73	        while (code.length() < 4) {
74	            code.append('0');
75	        }
76	        return code.toString();
77	    }
78	
79	    private static char digit(char c) {
80	        return switch (c) {
81	            case 'B', 'F', 'P', 'V' -> '1';
82	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
83	            case 'D', 'T' -> '3';
84	            case 'L' -> '4';
85	            case 'M', 'N' -> '5';
86	            case 'R' -> '6';
87	            default -> '0'; // A, E, I, O, U, H, W, Y
88	        };
89	    }
90	
91	    /**
92	     * Computes the SHA-256 digest of the UTF-8 bytes of {@code value} and renders it as a lower-case
93	     * hex string (64 characters). This is the single digest-to-hex routine reused across the
94	     * application; the upper-case variant simply upper-cases this result.
95	     *
96	     * @param value the string to hash
97	     * @return the full SHA-256 digest as lower-case hex
98	     */
99	    public static String sha256Hex(String value) {
100	        try {
101	            byte[] digest = MessageDigest.getInstance("SHA-256")
102	                .digest(value.getBytes(StandardCharsets.UTF_8));
103	            StringBuilder sb = new StringBuilder(digest.length * 2);
104	            for (byte b : digest) {
105	                sb.append(String.format("%02x", b));
106	            }
107	            return sb.toString();
108	        } catch (NoSuchAlgorithmException ex) {
109	            throw new IllegalStateException("SHA-256 not available", ex);
110	        }
111	    }
112	
113	    /**
114	     * Computes the SHA-256 digest of the UTF-8 bytes of {@code value} and renders it as an upper-case
115	     * hex string (64 characters). Delegates to {@link #sha256Hex(String)} so the digest-to-hex logic
116	     * lives in one place.
117	     *
118	     * @param value the string to hash
119	     * @return the full SHA-256 digest as upper-case hex
120	     */
121	    public static String sha256UpperHex(String value) {
122	        return sha256Hex(value).toUpperCase(Locale.ROOT);
123	    }
124	}
