318	    /**
319	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where REGION is
320	     * the region derived from the owner's postcode (preferring the postcode, falling back to the
321	     * city table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)}) and HASH8 is the
322	     * first 8 upper-case hex characters of the SHA-256 digest of the owner's normalized E.164
323	     * telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no
324	     * sequence number, so its base form is a stable function of the owner's region and
325	     * telephone/last-name identity rather than of creation order.
326	     *
327	     * <p>When that computed code already belongs to an existing owner it is de-duplicated by
328	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a code no
329	     * existing owner already has; the de-duplicated code is returned.
330	     *
331	     * @param owner the owner being created, with its telephone already normalized to E.164 form
332	     * @return the assigned, collision-free customer code
333	     */
334	    private String customerCodeFor(Owner owner) {
335	        String region = ownerMapper.regionOf(owner);
336	        String hash8 = IdentityKeyUtils.sha256UpperHex(owner.getTelephone() + owner.getLastName())
337	            .substring(0, 8);
338	        String baseCode = region + "-" + hash8;
339	        if (!isCustomerCodeInUse(baseCode)) {
340	            return baseCode;
341	        }
342	        int n = 2;
343	        String candidate = baseCode + "-" + n;
344	        while (isCustomerCodeInUse(candidate)) {
345	            n++;
346	            candidate = baseCode + "-" + n;
347	        }
348	        return candidate;
349	    }
