351	    /**
352	     * Determines whether any existing owner already carries the given {@code customerCode}, compared
353	     * exactly. Called while assigning a new owner's code so collisions can be de-duplicated.
354	     *
355	     * @param customerCode the candidate customer code to look for
356	     * @return {@code true} if an existing owner already has that customer code
357	     */
358	    private boolean isCustomerCodeInUse(String customerCode) {
359	        for (Owner existing : this.clinicService.findAllOwners()) {
360	            if (customerCode.equals(existing.getCustomerCode())) {
361	                return true;
362	            }
363	        }
364	        return false;
365	    }
