396	     * The fixed public holidays that the business-day roll skips. A registration date landing on one
397	     * of these dates is rolled forward, exactly as it is for a weekend day.
398	     */
399	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
400	        LocalDate.parse("2026-01-01"),
401	        LocalDate.parse("2026-01-26"),
402	        LocalDate.parse("2026-04-25"),
403	        LocalDate.parse("2026-12-25"),
