406	    /**
407	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday, a
408	     * Sunday or a listed public holiday is advanced one day at a time until it lands on a weekday
409	     * that is not a public holiday, while a date already on a non-holiday weekday is returned
410	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
411	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
412	     * falls on a business day.
413	     *
414	     * @param date the effective registration date
415	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
416	     */
417	    private static LocalDate rollToBusinessDay(LocalDate date) {
418	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
419	            date = date.plusDays(1);
420	        }
421	        return date;
422	    }
