543	    /**
544	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
545	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
546	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
547	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
548	     * string is what gets stored and returned.
549	     *
550	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
551	     *
552	     * <p>Once in E.164 form the national-number length is validated against the country code: a
553	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
554	     * number exactly 10 (see {@link E164PhoneNumbers#NATIONAL_LENGTHS}). Country codes without a configured
555	     * rule are accepted on the general 8-to-15 digit length alone.
556	     *
557	     * @param telephone the raw telephone value supplied by the client
558	     * @return the normalized E.164 telephone number
559	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
560	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
561	     *                                 after the {@code '+'}, or the wrong national-number length for
562	     *                                 its country code)
563	     */
564	    private static String normalizeTelephone(String telephone) {
565	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
566	        String digits;
567	        if (cleaned.startsWith("+")) {
568	            digits = cleaned.substring(1);
569	        } else {
570	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
571	            digits = "61" + national;
572	        }
573	        if (!digits.matches("[0-9]{8,15}")) {
574	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
575	                "telephone could not be normalized to a valid E.164 number");
576	        }
577	        validateNationalNumberLength(digits);
578	        return "+" + digits;
579	    }
580	
581	    /**
582	     * Validates the national-number length of an E.164 number (its digits, without the leading
583	     * {@code '+'}) against its country code. The longest dialling code that prefixes the number (see
584	     * {@link E164PhoneNumbers#countryCode}) selects the rule; if none is configured the number passes
585	     * (only the general 8-to-15 digit rule applies).
586	     *
587	     * @param digits the E.164 digits without the leading {@code '+'}
588	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
589	     *                                 digits does not match the country code's required length
590	     */
591	    private static void validateNationalNumberLength(String digits) {
592	        E164PhoneNumbers.countryCode(digits)
593	            .ifPresent(code -> {
594	                int nationalLength = digits.length() - code.length();
595	                int required = E164PhoneNumbers.NATIONAL_LENGTHS.get(code);
596	                if (nationalLength != required) {
597	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
598	                        "telephone must have " + required
599	                            + " national digits for country code +" + code);
600	                }
601	            });
602	    }
603	
604	    /**
605	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
606	     * containing at least one dot, none of the three sections containing whitespace or an
607	     * additional {@code @}.
608	     */
609	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
610	
611	    /**
612	     * Disposable email domains that are not accepted for an owner. An email whose domain is on this
613	     * blocklist is rejected with {@link HttpStatus#BAD_REQUEST}. Entries are lower-case and matched
614	     * case-insensitively against the domain (the part after the {@code @}).
615	     */
616	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
617	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
618	
619	    /**
620	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
621	     * (email is optional). When a value is supplied it must be a syntactically valid address whose
622	     * domain is not on the disposable-domain blocklist; the value is then stored and returned
623	     * lower-cased.
624	     *
625	     * @param email the raw email value supplied by the client, possibly {@code null}
626	     * @return the lower-cased email, or {@code null} when none was supplied
627	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
628	     *                                 is not a syntactically valid address, or its domain is on the
629	     *                                 disposable-domain blocklist
630	     */
631	    private static String normalizeEmail(String email) {
632	        if (email == null) {
633	            return null;
634	        }
635	        if (!EMAIL_PATTERN.matcher(email).matches()) {
636	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
637	                "email must be a syntactically valid address");
638	        }
639	        String normalized = email.toLowerCase(Locale.ROOT);
640	        String domain = normalized.substring(normalized.indexOf('@') + 1);
641	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
642	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
643	                "email domain " + domain + " is not allowed");
644	        }
645	        return normalized;
646	    }
