648	    /**
649	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
650	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
651	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
652	     */
653	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
654	        "NSW", new int[] {2000, 2099},
655	        "VIC", new int[] {3000, 3099},
656	        "QLD", new int[] {4000, 4099});
657	
658	    /**
659	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
660	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
661	     * four-digit format is enforced by request validation; here the value is range-checked: when the
662	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
663	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
664	     * accepts any four-digit postcode.
665	     *
666	     * @param city     the owner's city
667	     * @param postcode the owner's postcode, possibly {@code null}
668	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
669	     *                                 out of range for the city's region
670	     */
671	    private static void validatePostcode(String city, String postcode) {
672	        if (postcode == null) {
673	            return;
674	        }
675	        String region = OwnerMapper.CITY_REGION.get(city);
676	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
677	        if (range == null) {
678	            return;
679	        }
680	        int value = Integer.parseInt(postcode);
681	        if (value < range[0] || value > range[1]) {
682	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
683	                "postcode " + postcode + " is not valid for region " + region);
684	        }
685	    }
