687	    /**
688	     * Common street-type abbreviations expanded to their full word during address normalization.
689	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
690	     */
691	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
692	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
693	
694	    /**
695	     * Applies an owner's address, accepting either the structured form (a non-blank
696	     * {@code addressLine1} with an optional {@code addressLine2}) or the flat {@code address} form,
697	     * preferring the structured fields when present. Whichever fields are supplied are normalized
698	     * (see {@link #normalizeAddress(String)}), and the stored flat {@code address} is set to the
699	     * composed value: the normalized {@code addressLine1}, with a single space and the normalized
700	     * {@code addressLine2} appended when an {@code addressLine2} was supplied. When only the flat
701	     * form is supplied, the normalized flat address is stored and both structured lines are cleared.
702	     * This keeps the request contract backward-compatible: an owner that supplied just the flat
703	     * {@code address} (plus city) is still accepted.
704	     *
705	     * @param owner the owner being created or updated, carrying the raw address fields
706	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if neither a non-blank
707	     *                                 {@code addressLine1} nor a non-blank flat {@code address} was
708	     *                                 supplied
709	     */
710	    private static void applyAddress(Owner owner) {
711	        boolean hasStructured = owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank();
712	        boolean hasFlat = owner.getAddress() != null && !owner.getAddress().isBlank();
713	        if (!hasStructured && !hasFlat) {
714	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
715	                "an address must be supplied, either 'addressLine1' or 'address'");
716	        }
717	        if (hasStructured) {
718	            String line1 = normalizeAddress(owner.getAddressLine1());
719	            owner.setAddressLine1(line1);
720	            String composed = line1;
721	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
722	                String line2 = normalizeAddress(owner.getAddressLine2());
723	                owner.setAddressLine2(line2);
724	                composed = line1 + " " + line2;
725	            } else {
726	                owner.setAddressLine2(null);
727	            }
728	            owner.setAddress(composed);
729	        } else {
730	            owner.setAddressLine1(null);
731	            owner.setAddressLine2(null);
732	            owner.setAddress(normalizeAddress(owner.getAddress()));
733	        }
734	    }
735	
736	    /**
737	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
738	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
739	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
740	     * {@code AVE -> AVENUE}). This normalized value is what gets stored and returned.
741	     *
742	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
743	     *
744	     * @param address the raw address supplied by the client, possibly {@code null}
745	     * @return the normalized address
746	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
747	     *                                 after normalization (required field)
748	     */
749	    private static String normalizeAddress(String address) {
750	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
751	        if (collapsed.isEmpty()) {
752	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
753	                "address must not be blank");
754	        }
755	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
756	        StringBuilder normalized = new StringBuilder();
757	        for (int i = 0; i < tokens.length; i++) {
758	            if (i > 0) {
759	                normalized.append(' ');
760	            }
761	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
762	        }
763	        return normalized.toString();
764	    }
