766	    /**
767	     * Determines whether the given whole identity key already belongs to any owner other than the
768	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
769	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
770	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
771	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
772	     *
773	     * @param identityKey the identity key to look for
774	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
775	     * @return {@code true} if another owner already has the same identity key
776	     */
777	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
778	        for (Owner existing : this.clinicService.findAllOwners()) {
779	            if (existing.isDeleted()) {
780	                continue;
781	            }
782	            if (excludeId != null && excludeId.equals(existing.getId())) {
783	                continue;
784	            }
785	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
786	                return true;
787	            }
788	        }
789	        return false;
790	    }
