792	    /**
793	     * Finds the existing owner that the given (not-a-hard-duplicate) new owner is a possible
794	     * (soft) duplicate of: one whose identity key <em>differs</em> from the new owner's while sharing
795	     * the same last-name Soundex code (see {@link IdentityKeyUtils#soundex(String)}) and postcode. A
796	     * hard duplicate (identical identity key) has already been rejected with a 409 before this runs, so
797	     * this flags only the softer same-household-name overlap — in particular two owners with the same
798	     * last name and postcode but different telephones (whose identity keys therefore differ) are a soft
799	     * match rather than a rejected duplicate. The match with the lowest id is returned so the result is
800	     * deterministic when several owners qualify.
801	     *
802	     * @param owner the new owner being created, with its telephone already normalized
803	     * @return the matching existing owner, or {@code null} when none qualifies
804	     */
805	    private Owner findPossibleDuplicate(Owner owner) {
806	        if (owner.getLastName() == null || owner.getPostcode() == null) {
807	            return null;
808	        }
809	        String identityKey = ownerMapper.toIdentityKey(owner);
810	        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
811	        return this.clinicService.findAllOwners().stream()
812	            .filter(existing -> !existing.isDeleted())
813	            .filter(existing -> !identityKey.equals(ownerMapper.toIdentityKey(existing)))
814	            .filter(existing -> soundex.equals(IdentityKeyUtils.soundex(existing.getLastName())))
815	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
816	            .min(Comparator.comparingInt(Owner::getId))
817	            .orElse(null);
818	    }
819	
820	}
