254	        }
255	        for (Owner existing : ownerRepository.findAll()) {
256	            if (existing.isDeleted()) {
257	                continue;
258	            }
259	            if (excludeId != null && excludeId.equals(existing.getId())) {
260	                continue;
261	            }
262	            if (householdId.equals(existing.getHouseholdId())) {
263	                return true;
264	            }
265	        }
266	        return false;
267	    }
268	
269	    @Override
270	    public void assignHousehold(Owner owner) throws DataAccessException {
271	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
272	    }
273	
274	    /**
275	     * Normalizes a value for household comparison: leading/trailing whitespace is trimmed, internal
276	     * runs of whitespace are collapsed to a single space, and the result is lower-cased. This lets
277	     * two last names that differ only in case or whitespace be treated as the same household.
278	     *
279	     * @param value the raw value, possibly {@code null}
280	     * @return the normalized comparison key, or {@code ""} when the value is {@code null}
281	     */
282	    private static String normalizeForHousehold(String value) {
283	        if (value == null) {
284	            return "";
285	        }
286	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
287	    }
288	
289	    /**
290	     * Derives the stable household identifier shared by all owners with the same last name and
291	     * postcode. The value is deterministic (the first 12 upper-case hex characters of the SHA-256
292	     * digest of the normalized last name and the postcode, joined with {@code '|'}), so every owner
293	     * in the same household is assigned an identical identifier regardless of creation order and
294	     * without any explicit linking.
295	     *
296	     * @param lastName the owner's last name
297	     * @param postcode the owner's postcode, possibly {@code null}
298	     * @return the stable household identifier
299	     */
300	    private static String householdIdFor(String lastName, String postcode) {
301	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
302	        return IdentityKeyUtils.sha256UpperHex(key).substring(0, 12);
303	    }
304	
305	    @Override
306	    @Transactional(readOnly = true)
307	    public Collection<Visit> findVisitsByPetId(int petId) {
308	        return visitRepository.findByPetId(petId);
309	    }

