304	
305	    /**
306	     * The owner's current primary identifier, carried by the structured {@link OwnerCreatedEvent}.
307	     * Today an owner's primary identifier is its {@code customerCode}; this single accessor is the one
308	     * place that decides which field is primary, so if a later change unifies the customer code into a
309	     * member id, redirecting this method to the member id makes the audit event carry it instead.
310	     *
311	     * @param owner the created owner
312	     * @return the owner's current primary identifier
313	     */
314	    private String primaryIdentifier(Owner owner) {
315	        return owner.getCustomerCode();
316	    }
317	
318	    /**
319	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where REGION is
320	     * the region derived from the owner's postcode (preferring the postcode, falling back to the
321	     * city table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)}) and HASH8 is the
322	     * first 8 upper-case hex characters of the SHA-256 digest of the owner's normalized E.164
323	     * telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no
324	     * sequence number, so its base form is a stable function of the owner's region and
325	     * telephone/last-name identity rather than of creation order.
326	     *
327	     * <p>When that computed code already belongs to an existing owner it is de-duplicated by
328	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a code no
329	     * existing owner already has; the de-duplicated code is returned.
330	     *
331	     * @param owner the owner being created, with its telephone already normalized to E.164 form
332	     * @return the assigned, collision-free customer code
333	     */
334	    private String customerCodeFor(Owner owner) {
335	        String region = ownerMapper.regionOf(owner);
336	        String hash8 = IdentityKeyUtils.sha256UpperHex(owner.getTelephone() + owner.getLastName())
337	            .substring(0, 8);
338	        String baseCode = region + "-" + hash8;
339	        if (!isCustomerCodeInUse(baseCode)) {
340	            return baseCode;
341	        }
342	        int n = 2;
343	        String candidate = baseCode + "-" + n;
344	        while (isCustomerCodeInUse(candidate)) {
345	            n++;
346	            candidate = baseCode + "-" + n;
347	        }
348	        return candidate;
349	    }
350	
351	    /**
352	     * Determines whether any existing owner already carries the given {@code customerCode}, compared
353	     * exactly. Called while assigning a new owner's code so collisions can be de-duplicated.
354	     *
355	     * @param customerCode the candidate customer code to look for
356	     * @return {@code true} if an existing owner already has that customer code
357	     */
358	    private boolean isCustomerCodeInUse(String customerCode) {
359	        for (Owner existing : this.clinicService.findAllOwners()) {
360	            if (customerCode.equals(existing.getCustomerCode())) {
361	                return true;
362	            }
363	        }
364	        return false;
365	    }
366	
367	    /**
368	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
369	     * owner's city already contains this many owners.
370	     */
371	    private static final int CITY_CAPACITY = 50;
372	
373	    /**
374	     * The number of owners a city must already contain before a new owner in it is flagged with
375	     * {@code capacityWarning}. Once the city holds this many owners (but fewer than
376	     * {@link #CITY_CAPACITY}), the create still succeeds but is flagged as approaching the capacity
377	     * limit.
378	     */
379	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
380	
381	    /**
382	     * The maximum number of owners that may be created on a single day. A create is rejected with
383	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
384	     * {@code registrationDate}.
385	     */
386	    private static final int DAILY_CREATE_LIMIT = 100;
387	
388	    /**
389	     * The number of owners that must already have been created for the current day before a new
390	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
391	     * owners already carry today's {@code registrationDate}.
392	     */
393	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
394	
395	    /**
396	     * The fixed public holidays that the business-day roll skips. A registration date landing on one
397	     * of these dates is rolled forward, exactly as it is for a weekend day.
398	     */
399	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
400	        LocalDate.parse("2026-01-01"),
401	        LocalDate.parse("2026-01-26"),
402	        LocalDate.parse("2026-04-25"),
403	        LocalDate.parse("2026-12-25"),
404	        LocalDate.parse("2026-12-28"));
405	
406	    /**
407	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday, a
408	     * Sunday or a listed public holiday is advanced one day at a time until it lands on a weekday
409	     * that is not a public holiday, while a date already on a non-holiday weekday is returned
410	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
411	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
412	     * falls on a business day.
413	     *
414	     * @param date the effective registration date
415	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
416	     */
417	    private static LocalDate rollToBusinessDay(LocalDate date) {
418	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
419	            date = date.plusDays(1);
420	        }
421	        return date;
422	    }
423	
424	    private static boolean isWeekend(LocalDate date) {
425	        return switch (date.getDayOfWeek()) {
426	            case SATURDAY, SUNDAY -> true;
427	            default -> false;
428	        };
429	    }
430	
431	    /**
432	     * Counts the existing owners whose {@code registrationDate} equals the given (already
433	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
434	     * business day. Called before a new owner is saved, so the returned value reflects the number of
435	     * owners created for that day prior to this create.
436	     *
437	     * @param date the adjusted business-day registration date to count against
438	     * @return the number of existing owners registered on that date
439	     */
440	    private int countOwnersRegisteredOn(LocalDate date) {
441	        return (int) this.clinicService.findAllOwners().stream()
442	            .filter(existing -> date.equals(existing.getRegistrationDate()))
443	            .count();
444	    }
445	
446	    /**
447	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
448	     *
449	     * @param city the city to count owners for
450	     * @return the number of existing owners in that city
451	     */
452	    private int countOwnersInCity(String city) {
453	        return (int) this.clinicService.findAllOwners().stream()
454	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
455	            .count();
456	    }
457	
458	    /**
459	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
460	     * the last two digits of the fiscal year (which starts on 1 July) of the business-day-adjusted
461	     * registration date (e.g. {@code 'NSW-1A2B3C4D-M27'}). The fiscal year is derived via
462	     * {@link OwnerMapper#fiscalYear(LocalDate)}, the single source of truth also used by the DTO's
463	     * {@code fiscalYear} field.
464	     *
465	     * @param customerCode     the owner's assigned customer code
466	     * @param registrationDate the owner's business-day-adjusted registration date
467	     * @return the assigned membership number
468	     */
469	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
470	        String yy = String.format("%02d", OwnerMapper.fiscalYear(registrationDate) % 100);
471	        return String.format("%s-M%s", customerCode, yy);
472	    }
473	
474	    /**
475	     * Counts the existing owners that already share the given first name and last name, comparing
476	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
477	     * the number of namesakes that existed prior to this create.
478	     *
479	     * @param firstName the new owner's first name
480	     * @param lastName  the new owner's last name
481	     * @return the number of existing owners with the same first and last name
482	     */
483	    private int countNamesakes(String firstName, String lastName) {
484	        int count = 0;
485	        for (Owner existing : this.clinicService.findAllOwners()) {
486	            if (firstName.equalsIgnoreCase(existing.getFirstName())
487	                && lastName.equalsIgnoreCase(existing.getLastName())) {
488	                count++;
489	            }
490	        }
491	        return count;
492	    }
493	
494	    /**
495	     * Counts the existing owners that already belong to the given household (i.e. that share the
496	     * given {@code householdId}). Called before a new owner is saved, so adding one for the owner
497	     * being created yields the household's total size at the moment of creation. Owners without a
498	     * household id are ignored.
499	     *
500	     * @param householdId the new owner's assigned household id
501	     * @return the number of existing owners already in that household
502	     */
503	    private int countHouseholdMembers(String householdId) {
504	        if (householdId == null) {
505	            return 0;
506	        }
507	        int count = 0;
508	        for (Owner existing : this.clinicService.findAllOwners()) {
509	            if (householdId.equals(existing.getHouseholdId())) {
510	                count++;
511	            }
512	        }
513	        return count;
514	    }
515	
516	    /**
517	     * Computes the membership-level ceiling for a new owner joining the given household: one above the
518	     * current maximum effective membership level among the existing owners in that household. The
519	     * ceiling is frozen on the owner at creation and later applied by
520	     * {@link OwnerMapper#toMembershipLevel(Owner)}. Returns {@code null} when the household has no
521	     * existing member (or the owner has no household id), meaning no cap applies.
522	     *
523	     * @param householdId the new owner's assigned household id
524	     * @return one above the household's current maximum membership level, or {@code null} when the
525	     *         household has no existing member
526	     */
527	    private Integer householdMembershipLevelCap(String householdId) {
528	        if (householdId == null) {
529	            return null;
530	        }
531	        Integer maxLevel = null;
532	        for (Owner existing : this.clinicService.findAllOwners()) {
533	            if (householdId.equals(existing.getHouseholdId())) {
534	                int level = ownerMapper.toMembershipLevel(existing);
535	                if (maxLevel == null || level > maxLevel) {
536	                    maxLevel = level;
537	                }
538	            }
539	        }
540	        return maxLevel == null ? null : maxLevel + 1;
541	    }
542	
543	    /**
544	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
545	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
546	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
547	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
548	     * string is what gets stored and returned.
549	     *
550	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
551	     *
552	     * <p>Once in E.164 form the national-number length is validated against the country code: a
553	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
554	     * number exactly 10 (see {@link E164PhoneNumbers#NATIONAL_LENGTHS}). Country codes without a configured
555	     * rule are accepted on the general 8-to-15 digit length alone.
556	     *
557	     * @param telephone the raw telephone value supplied by the client
558	     * @return the normalized E.164 telephone number
559	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
560	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
561	     *                                 after the {@code '+'}, or the wrong national-number length for
562	     *                                 its country code)
563	     */
564	    private static String normalizeTelephone(String telephone) {
565	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
566	        String digits;
567	        if (cleaned.startsWith("+")) {
568	            digits = cleaned.substring(1);
569	        } else {
570	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
571	            digits = "61" + national;
572	        }
573	        if (!digits.matches("[0-9]{8,15}")) {
574	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
575	                "telephone could not be normalized to a valid E.164 number");
576	        }
577	        validateNationalNumberLength(digits);
578	        return "+" + digits;
579	    }
580	
581	    /**
582	     * Validates the national-number length of an E.164 number (its digits, without the leading
583	     * {@code '+'}) against its country code. The longest dialling code that prefixes the number (see
584	     * {@link E164PhoneNumbers#countryCode}) selects the rule; if none is configured the number passes
585	     * (only the general 8-to-15 digit rule applies).
586	     *
587	     * @param digits the E.164 digits without the leading {@code '+'}
588	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
589	     *                                 digits does not match the country code's required length
590	     */
591	    private static void validateNationalNumberLength(String digits) {
592	        E164PhoneNumbers.countryCode(digits)
593	            .ifPresent(code -> {
594	                int nationalLength = digits.length() - code.length();
595	                int required = E164PhoneNumbers.NATIONAL_LENGTHS.get(code);
596	                if (nationalLength != required) {
597	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
598	                        "telephone must have " + required
599	                            + " national digits for country code +" + code);
600	                }
601	            });
602	    }
603	
604	    /**
605	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
606	     * containing at least one dot, none of the three sections containing whitespace or an
607	     * additional {@code @}.
608	     */
609	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
610	
611	    /**
612	     * Disposable email domains that are not accepted for an owner. An email whose domain is on this
613	     * blocklist is rejected with {@link HttpStatus#BAD_REQUEST}. Entries are lower-case and matched
614	     * case-insensitively against the domain (the part after the {@code @}).
615	     */
616	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
617	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
618	
619	    /**
620	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
621	     * (email is optional). When a value is supplied it must be a syntactically valid address whose
622	     * domain is not on the disposable-domain blocklist; the value is then stored and returned
623	     * lower-cased.
624	     *
625	     * @param email the raw email value supplied by the client, possibly {@code null}
626	     * @return the lower-cased email, or {@code null} when none was supplied
627	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
628	     *                                 is not a syntactically valid address, or its domain is on the
629	     *                                 disposable-domain blocklist
630	     */
631	    private static String normalizeEmail(String email) {
632	        if (email == null) {
633	            return null;
634	        }
635	        if (!EMAIL_PATTERN.matcher(email).matches()) {
636	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
637	                "email must be a syntactically valid address");
638	        }
639	        String normalized = email.toLowerCase(Locale.ROOT);
640	        String domain = normalized.substring(normalized.indexOf('@') + 1);
641	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
642	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
643	                "email domain " + domain + " is not allowed");
644	        }
645	        return normalized;
646	    }
647	
648	    /**
649	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
650	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
651	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
652	     */
653	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
654	        "NSW", new int[] {2000, 2099},
655	        "VIC", new int[] {3000, 3099},
656	        "QLD", new int[] {4000, 4099});
657	
658	    /**
659	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
660	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
661	     * four-digit format is enforced by request validation; here the value is range-checked: when the
662	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
663	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
664	     * accepts any four-digit postcode.
665	     *
666	     * @param city     the owner's city
667	     * @param postcode the owner's postcode, possibly {@code null}
668	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
669	     *                                 out of range for the city's region
670	     */
671	    private static void validatePostcode(String city, String postcode) {
672	        if (postcode == null) {
673	            return;
674	        }
675	        String region = OwnerMapper.CITY_REGION.get(city);
676	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
677	        if (range == null) {
678	            return;
679	        }
680	        int value = Integer.parseInt(postcode);
681	        if (value < range[0] || value > range[1]) {
682	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
683	                "postcode " + postcode + " is not valid for region " + region);
684	        }
685	    }
686	
687	    /**
688	     * Common street-type abbreviations expanded to their full word during address normalization.
689	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
690	     */
691	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
692	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
693	
694	    /**
695	     * Applies an owner's address, accepting either the structured form (a non-blank
696	     * {@code addressLine1} with an optional {@code addressLine2}) or the flat {@code address} form,
697	     * preferring the structured fields when present. Whichever fields are supplied are normalized
698	     * (see {@link #normalizeAddress(String)}), and the stored flat {@code address} is set to the
699	     * composed value: the normalized {@code addressLine1}, with a single space and the normalized
700	     * {@code addressLine2} appended when an {@code addressLine2} was supplied. When only the flat
701	     * form is supplied, the normalized flat address is stored and both structured lines are cleared.
702	     * This keeps the request contract backward-compatible: an owner that supplied just the flat
703	     * {@code address} (plus city) is still accepted.
704	     *
705	     * @param owner the owner being created or updated, carrying the raw address fields
706	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if neither a non-blank
707	     *                                 {@code addressLine1} nor a non-blank flat {@code address} was
708	     *                                 supplied
709	     */
710	    private static void applyAddress(Owner owner) {
711	        boolean hasStructured = owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank();
712	        boolean hasFlat = owner.getAddress() != null && !owner.getAddress().isBlank();
713	        if (!hasStructured && !hasFlat) {
714	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
715	                "an address must be supplied, either 'addressLine1' or 'address'");
716	        }
717	        if (hasStructured) {
718	            String line1 = normalizeAddress(owner.getAddressLine1());
719	            owner.setAddressLine1(line1);
720	            String composed = line1;
721	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
722	                String line2 = normalizeAddress(owner.getAddressLine2());
723	                owner.setAddressLine2(line2);
724	                composed = line1 + " " + line2;
725	            } else {
726	                owner.setAddressLine2(null);
727	            }
728	            owner.setAddress(composed);
729	        } else {
730	            owner.setAddressLine1(null);
731	            owner.setAddressLine2(null);
732	            owner.setAddress(normalizeAddress(owner.getAddress()));
733	        }
734	    }
735	
736	    /**
737	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
738	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
739	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
740	     * {@code AVE -> AVENUE}). This normalized value is what gets stored and returned.
741	     *
742	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
743	     *
744	     * @param address the raw address supplied by the client, possibly {@code null}
745	     * @return the normalized address
746	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
747	     *                                 after normalization (required field)
748	     */
749	    private static String normalizeAddress(String address) {
750	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
751	        if (collapsed.isEmpty()) {
752	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
753	                "address must not be blank");
754	        }
755	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
756	        StringBuilder normalized = new StringBuilder();
757	        for (int i = 0; i < tokens.length; i++) {
758	            if (i > 0) {
759	                normalized.append(' ');
760	            }
761	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
762	        }
763	        return normalized.toString();
764	    }
765	
766	    /**
767	     * Determines whether the given whole identity key already belongs to any owner other than the
768	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
769	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
770	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
771	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
772	     *
773	     * @param identityKey the identity key to look for
774	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
775	     * @return {@code true} if another owner already has the same identity key
776	     */
777	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
778	        for (Owner existing : this.clinicService.findAllOwners()) {
779	            if (existing.isDeleted()) {
780	                continue;
781	            }
782	            if (excludeId != null && excludeId.equals(existing.getId())) {
783	                continue;
784	            }
785	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
786	                return true;
787	            }
788	        }
789	        return false;
790	    }
791	
792	    /**
793	     * Finds the existing owner that the given (not-a-hard-duplicate) new owner is a possible
794	     * (soft) duplicate of: one whose identity key <em>differs</em> from the new owner's while sharing
795	     * the same last-name Soundex code (see {@link IdentityKeyUtils#soundex(String)}) and postcode. A
796	     * hard duplicate (identical identity key) has already been rejected with a 409 before this runs, so
797	     * this flags only the softer same-household-name overlap — in particular two owners with the same
798	     * last name and postcode but different telephones (whose identity keys therefore differ) are a soft
799	     * match rather than a rejected duplicate. The match with the lowest id is returned so the result is
800	     * deterministic when several owners qualify.
801	     *
802	     * @param owner the new owner being created, with its telephone already normalized
803	     * @return the matching existing owner, or {@code null} when none qualifies
804	     */
805	    private Owner findPossibleDuplicate(Owner owner) {
806	        if (owner.getLastName() == null || owner.getPostcode() == null) {
807	            return null;
808	        }
809	        String identityKey = ownerMapper.toIdentityKey(owner);
810	        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
811	        return this.clinicService.findAllOwners().stream()
812	            .filter(existing -> !existing.isDeleted())
813	            .filter(existing -> !identityKey.equals(ownerMapper.toIdentityKey(existing)))
814	            .filter(existing -> soundex.equals(IdentityKeyUtils.soundex(existing.getLastName())))
815	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
816	            .min(Comparator.comparingInt(Owner::getId))
817	            .orElse(null);
818	    }
819	
820	}
