/**
 * The {@code '<REGION><FY><HASH8><CHK>'} base of a member id, dropping any {@code '-<n>'} collision
 * suffix, or {@code null} when the owner has no (well-formed) member id yet. The trailing segments
 * have fixed widths — FY (2 digits), HASH8 (8 hex) and CHK (1 digit) — so REGION and FY can be
 * recovered from the base by position: REGION is everything before the trailing 11 characters and
 * FY is the two characters immediately preceding HASH8 and CHK.
 */
private static String memberIdBase(String memberId) {
    if (memberId == null) {
        return null;
    }
    int dash = memberId.indexOf('-');
    String base = dash >= 0 ? memberId.substring(0, dash) : memberId;
    // A well-formed base is REGION (>= 1 char) + FY (2) + HASH8 (8) + CHK (1) = > 11 characters.
    return base.length() > 11 ? base : null;
}

